class _Backdrop extends State<Backdrop> with SingleTickerProviderStateMixin{late final AnimationController c=AnimationController(vsync:this,duration:const Duration(seconds:14))..repeat();@override void dispose(){c.dispose();super.dispose();}@override Widget build(BuildContext x)=>AnimatedBuilder(animation:c,builder:(_,__) {final p=math.sin(c.value*math.pi*2)*80;return Stack(children:[Positioned(left:p-120,top:60,child:const Glow(Color(0xFFFF4D5D),310)),Positioned(right:-130-p,top:300,child:const Glow(Color(0xFF5136FF),360)),Positioned.fill(child:IgnorePointer(child:CustomPaint(painter:Grid()))) ]);});}
