class Grid extends CustomPainter{@override void paint(Canvas c,Size s){final p=Paint()..color=Colors.white.withOpacity(.018);for(double x=0;x<s.width;x+=42){c.drawLine(Offset(x,0),Offset(x,s.height),p);}for(double y=0;y<s.height;y+=42){c.drawLine(Offset(0,y),Offset(s.width,y),p);}}@override bool shouldRepaint(covariant CustomPainter oldDelegate)=>false;}
